line-height:1.9}.copy{border-top:1px solid rgba(255,255,255,.12);margin-top:22px;padding-top:14px;font-size:9px;color:#8fa1b7}@media(max-width:1080px){.nav-links{display:none}.menu-toggle{display:grid;place-items:center}.hero-grid,.about{grid-template-columns:1fr}.services{grid-template-columns:repeat(2,1fr)}.industries{grid-template-columns:repeat(4,1fr)}.why{grid-template-columns:repeat(3,1fr)}.split{grid-template-columns:1fr}.gallery{grid-template-columns:1fr 1fr}.gallery img:first-child{height:185px;grid-row:auto}.trust-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.nav-actions .btn:not(.red),.lang{display:none}.hero{min-height:620px;background-position:72% center}.hero h1{font-size:37px}.trust-grid,.stats,.process{grid-template-columns:1fr 1fr}.services{grid-template-columns:1fr}.industries,.why{grid-template-columns:1fr 1fr}.points{grid-template-columns:1fr}.maintenance,.portal{padding:28px}.gallery{grid-template-columns:1fr 1fr}.emergency,.cta{align-items:flex-start;flex-direction:column}.footer-grid{grid-template-columns:1fr 1fr}.section{padding:52px 0}}@media(max-width:450px){.nav-actions .btn.red{display:none}.hero h1{font-size:31px}.actions{display:grid}.actions .btn{width:100%}.trust-grid,.stats,.process,.why,.footer-grid{grid-template-columns:1fr}.industries{grid-template-columns:1fr 1fr}.gallery{grid-template-columns:1fr}.gallery img{height:190px}.photo img{height:320px}}</style></head><body>
